function localOperation(message){const m=message.trim();if(/fix.*(?:issues|all)/i.test(m))return [{type:'fix',target:'',value:''}];if(/(?:larger|bigger|increase.*(?:text|font))/i.test(m))return [{type:'style',target:'fontSize',value:String(Math.min(28,book.tokens.fontSize+2))}];if(/(?:smaller|decrease.*(?:text|font))/i.test(m))return [{type:'style',target:'fontSize',value:String(Math.max(16,book.tokens.fontSize-2))}];if(/(?:increase|more).*(?:space|spacing)/i.test(m))return [{type:'style',target:'space',value:String(Math.min(40,book.tokens.space+4))}];if(/(?:less|decrease).*(?:space|spacing)/i.test(m))return [{type:'style',target:'space',value:String(Math.max(12,book.tokens.space-4))}];if(/high(?:er)? contrast/i.test(m))return [{type:'style',target:'ink',value:'#152c24'},{type:'style',target:'paper',value:'#ffffff'},{type:'style',target:'accent',value:'#194e3b'},{type:'style',target:'surface',value:'#eff7f1'}];const color=m.match(/(?:accent|color|colour).*?(#[a-f0-9]{6})/i);if(color)return [{type:'style',target:'accent',value:color[1]}];const font=m.match(/(?:font|text).*?(\d{2})\s*(?:px|pixels)?$/i);if(font)return [{type:'style',target:'fontSize',value:font[1]}];const edit=m.match(/^replace\s+([\w-]+)\s+with\s+["“]([\s\S]+)["”]$/i);if(edit)return [{type:'text',target:edit[1],value:edit[2]}];return []}
