async function applyOps(ops,{ai=false}={}){if(ai)verifyOps(ops);const checkpoint={design:structuredClone(book.design||null),files:new Map(book.files),tokens:{...book.tokens},reviewed:structuredClone(book.reviewed),mappings:{...book.mappings},assetRepairs:[...book.assetRepairs],editedBindings:[...book.editedBindings],applied:book.applied,log:[...book.log]},oldHistory=[...book.history];try{const styleOps=ops.filter(o=>o.type==='style');if(styleOps.length){const tokens={...book.tokens};for(const o of styleOps)tokens[o.target]=typeof defaults[o.target]==='number'?Number(o.value):o.value;if(book.design?.draft)updateCompositionTokens(book,tokens);else book.applyStyle(tokens,css,componentSource)}for(const o of ops){if(o.type==='text')book.replaceText(page().href,o.target,o.value);if(o.type==='alt')book.setAlt(page().href,+o.target,o.value,false);if(o.type==='label')book.setLabel(page().href,+o.target,o.value);if(o.type==='component')book.component(page().href,o.value);if(o.type==='fix')book.fixSupported(css,componentSource)}book.history=[...oldHistory,checkpoint].slice(-12);refresh();await showPreview()}catch(e){Object.assign(book,checkpoint);book.history=oldHistory;book.revision++;throw e}}
