const gotoPDF=n=>{if(!source)return;markSave();pdfPage=Math.max(1,Math.min(source.inventory.length,n));showPreview()};$('#pdf-prev').onclick=()=>gotoPDF(pdfPage-1);$('#pdf-next').onclick=()=>gotoPDF(pdfPage+1);$('#pdf-page').onchange=e=>gotoPDF(+e.target.value||1);let cropStart=null;const wrap=$('#pdf-canvas-wrap');wrap.onpointerdown=e=>{if(!cropping)return;const r=wrap.getBoundingClientRect();cropStart={x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))};wrap.setPointerCapture(e.pointerId);crop=null;$('#crop-box').hidden=false};wrap.onpointermove=e=>{if(!cropStart)return;const r=wrap.getBoundingClientRect(),x=Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y=Math.max(0,Math.min(1,(e.clientY-r.top)/r.height));crop={x:Math.min(x,cropStart.x),y:Math.min(y,cropStart.y),w:Math.abs(x-cropStart.x),h:Math.abs(y-cropStart.y)};Object.assign($('#crop-box').style,{left:crop.x*100+'%',top:crop.y*100+'%',width:crop.w*100+'%',height:crop.h*100+'%'})};wrap.onpointercancel=()=>{cropStart=null};wrap.onpointerup=()=>{cropStart=null;$('#use-crop').disabled=!assetSelection||!crop||crop.w<.01||crop.h<.01};$('#use-crop').onclick=()=>run(async()=>{if(!assetSelection||!crop)throw Error('Choose an image and a source crop first.');progress('Replacing the selected artwork','Saving the source coordinates and image hash.');const src=$('#pdf-canvas'),canvas=document.createElement('canvas');canvas.width=Math.round(crop.w*src.width);canvas.height=Math.round(crop.h*src.height);canvas.getContext('2d').drawImage(src,Math.round(crop.x*src.width),Math.round(crop.y*src.height),canvas.width,canvas.height,0,0,canvas.width,canvas.height);const ext=assetSelection.path?.split('.').pop().toLowerCase();if(!assetSelection.path)throw Error('This image does not have a local asset path.');const newPath=['png','jpg','jpeg','webp'].includes(ext)?assetSelection.path:assetSelection.path.replace(/\.[^.]+$/,'')+'-folio-crop.png';const mime=ext==='webp'?'image/webp':['jpg','jpeg'].includes(ext)?'image/jpeg':'image/png';const blob=await new Promise(r=>canvas.toBlob(r,mime,.96));const bytes=new Uint8Array(await blob.arrayBuffer());const prior=book.files.get(assetSelection.path);book.snapshot('Re-extracted '+assetSelection.path+' from PDF page '+pdfPage);book.write(newPath,bytes);if(newPath!==assetSelection.path){const d=book.doc(assetSelection.href);d.querySelectorAll('#content img')[assetSelection.index].setAttribute('src',relative(assetSelection.href,newPath));book.write(assetSelection.href,serialize(d));}book.assetRepairs.push({href:assetSelection.href,imageIndex:assetSelection.index,path:newPath,previousPath:assetSelection.path,pdfSHA256:source.hash,page:pdfPage,renderSize:[src.width,src.height],cropNormalized:crop,beforeSHA256:prior?await sha(prior):null,afterSHA256:await sha(bytes),reason:'Editor selected the verified source artwork'});refresh();setCropping(false);previewMode='book';await showPreview();toast('Artwork replaced. The source crop and affected image are recorded in the report.');});
